//! libxc's per-point input screening and sanitisation.
//!
//! GENERATED by tools/translate_rayon/gen_eval.py -- do not hand-edit.
//!
//! libxc does two separate things at the top of `work_{lda,gga,mgga}_inc.c`,
//! before the maple2c body ever runs:
//!
//! 1. **Screen.** `if(dens < p->dens_threshold) continue;` -- the point keeps
//!    whatever the caller's buffer held (libxc leaves it; this tree writes
//!    zero, which is what `xc_*_exc_vxc` produces for a freshly zeroed output).
//! 2. **Sanitise.** Clamp the inputs it *is* going to use:
//!
//!    ```c
//!    my_rho[0]   = m_max(p->dens_threshold, rho[0]);
//!    my_sigma[0] = m_max(p->sigma_threshold * p->sigma_threshold, sigma[0]);
//!    if(NEEDS_TAU){
//!      my_tau[0] = m_max(p->tau_threshold, tau[0]);
//!      my_sigma[0] = m_min(my_sigma[0], 8.0*my_rho[0]*my_tau[0]);  /* Fermi hole */
//!    }
//!    /* polarized: the same for spin 1, then */
//!    s_ave = 0.5*(my_sigma[0] + my_sigma[2]);
//!    my_sigma[1] = clamp(my_sigma[1], -s_ave, +s_ave);
//!    ```
//!
//! Only (1) was reproduced here. (2) was not, and it is not cosmetic: the
//! Fermi-hole clamp is on by default in libxc's own CMake (`if(NOT DISABLE_FHC)`
//! -> `-DXC_ENFORCE_FERMI_HOLE_CURVATURE`), so the oracle this library is
//! measured against has it. That is where `mgga_c_r2scan`'s `vtau` and
//! `mgga_x_scan`'s polarized `vsigma` disagreed: a random grid feeds `tau`
//! below the von Weizsaecker bound `sigma/(8 rho)`, libxc clamps `sigma` down
//! to `8 rho tau` there and this tree did not. The `+-s_ave` clamp on the
//! cross term is the same story for polarized GGA and MGGA.
//!
//! The clamps are the identity on a physical quadrature -- `sigma_ab` really
//! is bounded by `(sigma_aa+sigma_bb)/2`, `tau` really does satisfy the von
//! Weizsaecker bound -- which is why [`Sanitised::needed`] exists: the common
//! case is detected in one pass and the kernel then runs on the caller's own
//! slices with no copy at all.

use libxc_core::model::Thresholds;

/// libxc's `m_max` (`util.h`), which is **not** `f64::max`.
///
/// ```c
/// #define m_max(x,y)  (((x)<(y)) ? (y) : (x))
/// ```
///
/// The difference is visible on NaN: `m_max(t, NAN)` is `t`, because `t < NAN`
/// is false, while `f64::max` returns the non-NaN operand and would give `t`
/// too -- but `m_max(NAN, t)` is `NAN` where `f64::max` gives `t`. Reproducing
/// the ternary is cheaper than reasoning about which way round each call is.
#[inline(always)]
pub fn m_max(x: f64, y: f64) -> f64 {
    if x < y { y } else { x }
}

/// libxc's `m_min` (`util.h`): `(((x)<(y)) ? (x) : (y))`.
#[inline(always)]
pub fn m_min(x: f64, y: f64) -> f64 {
    if x < y { x } else { y }
}

/// The thresholds one `work_*_inc.c` point-loop applies, resolved once per
/// dispatch instead of once per point.
#[derive(Clone, Copy, Debug)]
pub struct Screen {
    /// `p->dens_threshold`. Both the screen and the `my_rho` clamp.
    pub dens: f64,
    /// `p->sigma_threshold * p->sigma_threshold` -- libxc squares it at every
    /// use, so it is squared once here.
    pub sigma2: f64,
    /// `p->tau_threshold`.
    pub tau: f64,
    /// `p->info->flags & XC_FLAGS_NEEDS_TAU`.
    ///
    /// Set means `work_mgga_inc.c` clamps `tau` up to `tau_threshold` and then
    /// clamps `sigma` down to the Fermi-hole curvature bound `8 rho tau`.
    /// Clear means neither happens.
    pub needs_tau: bool,
    /// Pass `tau = 0.0` to the kernel rather than the caller's value.
    ///
    /// libxc declares `my_tau[2] = {0.0, 0.0}` outside its point loop and
    /// writes it only under `XC_FLAGS_NEEDS_TAU`, so a functional without the
    /// flag is evaluated at `tau = 0` -- whatever the caller passed.
    ///
    /// For 23 of the 24 such functionals the kernel loads `tau` and never
    /// reads the binding, so the caller's value can go straight through: same
    /// bits out, and no sanitised copy. `mgga_x_2d_prhg07_prp10` is the one
    /// that does read it (`XC_FLAGS_2D | XC_FLAGS_NEEDS_LAPLACIAN`, no
    /// `NEEDS_TAU`, and a maple2c body that uses `tau` anyway), and it gets
    /// the zeros. `gen_eval.py::kernel_reads_tau` decides this per kernel from
    /// the emitted source rather than assuming either way.
    pub zero_tau: bool,
}

/// Can one set of *input clamps* stand in for all of `legs` on this grid?
///
/// A fused composite kernel (`crate::fused`) evaluates every auxiliary of a
/// mix in one loop over one set of inputs, sharing subexpressions between
/// them. libxc gives each auxiliary its own `dens_threshold` -- `xc_mix_init`
/// calls `xc_func_init` per aux, so each keeps its own
/// `info->dens_threshold` -- and hence its own screen, its own `my_rho` clamp,
/// and its own `sigma_threshold = dens_threshold^(4/3)`. HSE06's legs are
/// `gga_x_wpbeh` twice at 1e-14 and `gga_c_pbe` at 1e-12; PBE0's are
/// `gga_x_pbe` at 1e-15 and `gga_c_pbe` at 1e-12.
///
/// The *screen* is reproduced inside the fused kernel, per leg: each leg's
/// accumulation is guarded by its own `dens_threshold`, so a point below one
/// leg's threshold and above another's contributes to the second only. What
/// cannot be reproduced there is the *clamp*, because a clamped input is a
/// different input and the whole point of fusing is that the legs share one.
///
/// So the fused path is exact exactly where no leg that survives its own
/// screen would have had an input clamped. That is the common case by a wide
/// margin: `rho` below `dens_threshold` at a point whose total density is
/// above it means one spin channel is essentially empty, and `sigma` below
/// `dens_threshold^(8/3)` (1e-32 at the largest threshold here) at a point
/// with any density at all means a numerically exact density extremum. Points
/// below every leg's threshold are skipped -- they contribute nothing either
/// way, so a molecular grid's empty tail does not disqualify the grid.
///
/// It is a whole-grid, all-or-nothing test: one linear pass over inputs the
/// kernel is about to read anyway. When it says no, the caller runs the mix,
/// which clamps per auxiliary and is correct by construction.
///
/// `zeta` is compared exactly rather than bounded: it reaches the maple2c
/// bodies as a *value*, not as a cutoff, and the fused kernels take one.
#[must_use]
pub fn fused_legs_agree(
    rho: &[f64],
    sigma: &[f64],
    np: usize,
    nc: usize,
    ns: usize,
    legs: &[Thresholds],
) -> bool {
    let Some(first) = legs.first() else { return true };
    if legs.iter().any(|t| t.zeta.to_bits() != first.zeta.to_bits()) {
        return false;
    }

    for ip in 0..np {
        let dens = if nc == 1 { rho[ip] } else { rho[ip * 2] + rho[ip * 2 + 1] };
        for t in legs {
            // A leg below its own threshold is screened out at this point, so
            // whatever its clamps would have done is never observed.
            if dens < t.density {
                continue;
            }
            for c in 0..nc {
                // `m_max(dens_threshold, rho)` returns `rho` iff this holds.
                if !(t.density <= rho[ip * nc + c]) {
                    return false;
                }
            }
            let s2 = t.sigma * t.sigma;
            // Diagonal sigma only: `sigma[1]` is a cross term, may legitimately
            // be negative, and its own `+-s_ave` clamp is built from the two
            // diagonals -- so once those are unclamped it is identical across
            // legs, whether or not it bites.
            if !(s2 <= sigma[ip * ns]) {
                return false;
            }
            if ns == 3 && !(s2 <= sigma[ip * ns + 2]) {
                return false;
            }
        }
    }
    true
}

impl Screen {
    /// The screen `xc_func_init` + `work_*_inc.c` give a functional with these
    /// thresholds and this `NEEDS_TAU` flag.
    #[inline]
    #[must_use]
    pub fn new(t: &Thresholds, needs_tau: bool, zero_tau: bool) -> Self {
        Self {
            dens: t.density,
            sigma2: t.sigma * t.sigma,
            tau: t.tau,
            needs_tau,
            zero_tau,
        }
    }
}
